void Solver::restart() {
    // Reset LBD statistics
    fast_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;

    // Backtrack to root level
    backtrack(0);

    // Decay VSIDS activity to diversify the search space
    for (int v = 1; v <= vars; ++v) {
        activity[v] *= 0.5;
        if (vsids.inHeap(v)) vsids.update(v);
    }

    // Rephase variables: 70% keep local best, 10% invert, 20% random
    int r = rand() % 100;
    if (r < 70) {
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 80) {
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }

    // Reset rephase and reduce counters/limits
    rephases = 0;
    reduces = 0;
    rephase_limit = 8192;
    reduce_limit = 512;
}
